model.addConstrs(
    z[i, k] + gp.quicksum(y[j] for j in range(n) if c[i][j] < D[i][k]) >= 1
    for i in range(n)
    for k in range(1, G[i])
)

model.setObjective(
    gp.quicksum(
        (D[i][k] - D[i][k-1]) * z[i, k]
        for i in range(n)
        for k in range(1, G[i])
    ),
    GRB.MINIMIZE,
)
